function teamNames(name){return String(name||'').split(/\s+(?:–|—|-|vs\.?|v\.)\s+/i).map(x=>x.trim()).filter(Boolean).slice(0,2)}
function dsFallbackCrest(team){const name=String(team||'').trim();const words=name.replace(/^(FC|CF|SC|FK|AC|AFC)\s+/i,'').split(/\s+/).filter(Boolean);const initials=(words.length>1?words.slice(0,2).map(w=>w[0]).join(''):name.slice(0,2)).toUpperCase().slice(0,3);let h=0;for(const ch of name)h=(h*31+ch.charCodeAt(0))>>>0;const hue=h%360;const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 72"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="hsl('+hue+',52%,39%)"/><stop offset="1" stop-color="hsl('+hue+',62%,19%)"/></linearGradient></defs><path d="M32 3 58 12 56 44Q52 59 32 69 12 59 8 44L6 12Z" fill="url(#g)" stroke="#e7d5a6" stroke-width="3"/><path d="M32 9 51 16 50 43Q47 54 32 62 17 54 14 43L13 16Z" fill="none" stroke="#ffffff66" stroke-width="1.5"/><text x="32" y="40" fill="#fff9e8" text-anchor="middle" font-size="19" font-weight="800" font-family="Arial,sans-serif">'+initials.replace(/[^A-Z0-9]/g,'')+'</text></svg>';return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}
function crestHTML(team,league){const flag=dsNationalFlag(team,league);const country=(dsCountry(league)||[])[2]||'';return '<span class="ds11-crest'+(flag?' ds15-national':'')+'" data-team="'+esc(team)+'" data-national="'+(flag?'1':'0')+'" data-country="'+esc(country)+'">'+'<span class="ds-crest-placeholder" aria-label="Емблемата не е налична">⚽</span>'+'</span>'}
const crestLookupCache=new Map();
function crestLookup(team,country){const key=(team+'|'+(country||'')).trim().toLowerCase();if(crestLookupCache.has(key))return crestLookupCache.get(key);const task=(async()=>{try{const cached=localStorage.getItem('ds-crest-v22:'+key);if(cached)return cached}catch(e){}try{const r=await fetch('/api/crests?team='+encodeURIComponent(team)+'&country='+encodeURIComponent(country||''));if(!r.ok)return null;const d=await r.json();if(d.url){try{localStorage.setItem('ds-crest-v22:'+key,d.url)}catch(e){}return d.url}}catch(e){}return null})();crestLookupCache.set(key,task);return task}
