function hydrateCrests(){
 const els=[...document.querySelectorAll('.ds11-crest[data-team]')];if(!els.length)return;
 if(!crestManifestPromise)crestManifestPromise=fetch('/crests/manifest.json?v=221').then(r=>r.ok?r.json():{}).catch(()=>({}));
 crestManifestPromise.then(map=>{const names=[...new Set(els.map(el=>el.dataset.team))];for(const name of names){
  const targets=els.filter(el=>el.dataset.team===name);const key=name.toLowerCase();const national=targets[0]?.dataset.national==='1';
  Promise.resolve(national?crestLookup(name,targets[0]?.dataset.country):map[key]||crestLookup(name,targets[0]?.dataset.country)).then(src=>{if(!src)return;for(const el of targets){if(!el.isConnected)return;const img=document.createElement('img');img.src=src;img.alt='Емблема '+name;img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{img.onerror=null;img.replaceWith(document.createTextNode('⚽'));el.classList.remove('has-crest')};el.replaceChildren(img);el.classList.add('has-crest')}})
 }})
}
function confidence(p){const m=String(p.level||'').match(/(?:^|\D)(10|[1-9])\s*\/\s*10/);return m?m[1]+'/10':'—'}
function shortPick(value,match){
 let s=String(value||'').trim();const teams=teamNames(match);
 if(teams.length===2){if(s.toLowerCase()===(teams[0]+' да допусне гол').toLowerCase())return teams[1]+' +0.5 гола';if(s.toLowerCase()===(teams[1]+' да допусне гол').toLowerCase())return teams[0]+' +0.5 гола'}
 s=s.replace(/^Без равенство във? (първото|второто) полувреме$/i,(_,h)=>'12 '+(h.toLowerCase().startsWith('п')?'FH':'2H'));
 s=s.replace(/^И двата отбора да вкарат$/i,'Гол/Гол');
 s=s.replace(/^Мачът (над|под) ([\d.,]+) (гола|картона|корнера|удара във вратата|удара)(?: във? (първото|второто) полувреме)?$/i,(_,dir,n,market,half)=>(dir.toLowerCase()==='над'?'+':'−')+n+' '+(market==='удара във вратата'?'точни удара':market)+(half?' '+(half.toLowerCase().startsWith('п')?'FH':'2H'):''));
 s=s.replace(/^(.+?) да вкара гол \(над 0[.,]5\)$/i,'$1 +0.5 гола');
 s=s.replace(/^(.+?) да не загуби (първото|второто) полувреме$/i,(_,team,half)=>team+' X2 '+(half.toLowerCase().startsWith('п')?'FH':'2H'));
 s=s.replace(/над ([\d.,]+) удара във вратата/gi,'+$1 точни удара').replace(/над ([\d.,]+) корнера/gi,'+$1 корнера').replace(/над ([\d.,]+) гола/gi,'+$1 гола').replace(/под ([\d.,]+) гола/gi,'−$1 гола');
 return s;
}
