 const all='<section class="ds19-daily ds20-all"><div class="ds19-section-head"><h2>Всички селекции</h2><span>'+games.length+' мача · '+selections.length+' селекции</span></div><div class="ds19-fixtures">'+(games.length?games.map(groupedCard).join(''):empty('Няма селекции за днес.'))+'</div><button class="ds19-see-all" data-goto="matches">Търсене и филтри ›</button></section>';
