 const sheetMarkup=mine?sheetRows.map(p=>'<article class="match-card"><div class="match-top"><span>'+esc(p.date)+' · '+fmt(p.legs)+' селекции · Google Sheets</span>'+badge(p.status)+'</div><div class="match-title">'+esc(p.match)+'</div><div class="match-pick"><span>'+esc(shortPick(p.selection,p.match))+'</span><b>'+fmt(p.odds)+'</b></div>'+(p.pl!==null?'<div class="match-meta '+color(p.pl)+'">Резултат '+signed(p.pl)+' u</div>':'')+'</article>').join(''):sheetRows.map(dsBuilderCard).join('');
 const oracleMarkup=oracleRows.map(oracleBuilderCard).join('');
