 const prev=$('#builder-prev'),next=$('#builder-next');if(prev)prev.onclick=()=>{builderHistoryState.offset=Math.max(0,builderHistoryState.offset-builderHistoryState.limit);render()};if(next)next.onclick=()=>{builderHistoryState.offset+=builderHistoryState.limit;render()};hydrateCrests();
