function chart(points){
 const ordered=[...(points||[])].filter(p=>p&&p.date&&Number.isFinite(Number(p.pl))).sort((a,b)=>{const date=x=>/^\d{2}\.\d{2}\.\d{4}$/.test(x)?x.split('.').reverse().join('-'):x;return date(a.date).localeCompare(date(b.date))});
 if(!ordered.length)return '<div class="ds12-chart-empty"><b>Все още няма приключили залози</b><span>Графиката ще се появи след първия отчетен резултат.</span></div>';
 let total=0;const values=[{date:'Начало',value:0},...ordered.map(p=>({date:p.date,value:total+=Number(p.pl)}))];
 const w=720,h=254,l=48,r=18,t=18,b=40;const low=Math.min(0,...values.map(v=>v.value)),high=Math.max(0,...values.map(v=>v.value));const pad=Math.max((high-low)*.14,1);const min=low-pad,max=high+pad;const x=i=>l+(w-l-r)*(i/(values.length-1||1)),y=v=>t+(h-t-b)*(max-v)/(max-min||1);
 const coords=values.map((v,i)=>[x(i),y(v.value)]);const path=coords.map(([px,py],i)=>(i?'L':'M')+px.toFixed(1)+' '+py.toFixed(1)).join(' ');const area=path+' L'+x(values.length-1).toFixed(1)+' '+(h-b)+' L'+l+' '+(h-b)+' Z';const zero=y(0);const ticks=Array.from({length:5},(_,i)=>min+(max-min)*i/4);
 const grid=ticks.map(v=>'<line x1="'+l+'" y1="'+y(v).toFixed(1)+'" x2="'+(w-r)+'" y2="'+y(v).toFixed(1)+'" stroke="#2b4056" stroke-dasharray="4 6" stroke-width="1"/><text x="'+(l-9)+'" y="'+(y(v)+4).toFixed(1)+'" text-anchor="end" fill="#8fa6bd" font-size="12">'+esc(fmt(v))+'</text>').join('');
 const last=coords[coords.length-1],start=ordered[0].date,end=ordered[ordered.length-1].date;
 return '<div class="ds12-chart"><div class="ds12-chart-head"><div><small>НАТРУПАНА ПЕЧАЛБА</small><strong class="'+color(total)+'">'+signed(total)+' u</strong></div><span class="ds12-chart-count">'+ordered.length+' отчетни дни</span></div><svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Натрупана печалба от '+esc(start)+' до '+esc(end)+'"><defs><linearGradient id="ds12Fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#25e9ac" stop-opacity=".32"/><stop offset="100%" stop-color="#25e9ac" stop-opacity="0"/></linearGradient><linearGradient id="ds12Stroke" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stop-color="#05bdb8"/><stop offset="100%" stop-color="#3df6a2"/></linearGradient></defs>'+grid+'<line x1="'+l+'" y1="'+zero.toFixed(1)+'" x2="'+(w-r)+'" y2="'+zero.toFixed(1)+'" stroke="#7995ab" stroke-opacity=".7" stroke-width="1.3"/><path d="'+area+'" fill="url(#ds12Fill)"/><path d="'+path+'" fill="none" stroke="url(#ds12Stroke)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="'+last[0].toFixed(1)+'" cy="'+last[1].toFixed(1)+'" r="6" fill="#31efaa" stroke="#0d2431" stroke-width="3"/><text x="'+l+'" y="'+(h-10)+'" fill="#a4bbd1" font-size="13">'+esc(start)+'</text><text x="'+(w-r)+'" y="'+(h-10)+'" text-anchor="end" fill="#a4bbd1" font-size="13">'+esc(end)+'</text></svg><div class="ds12-chart-foot"><span>0 u = начално ниво</span><span>Печалба в единици (u)</span></div></div>';
}
async function statistics(){
 let historicalPanel='';
 try{const rr=await fetch('/api/oracle-stats?sources='+strategyKeys.join(','),{headers:{Authorization:'Bearer '+state.token},cache:'no-store'});if(!rr.ok)throw Error('Oracle HTTP '+rr.status);const full=await rr.json();if(!full.selected||!Array.isArray(full.groups))throw Error('Невалидни данни');historicalPanel=ds19StatsPanel(full.selected,full,full.groups.map(g=>({...g,...g.stats})),true)}catch(e){historicalPanel='<section class="ds19-history"><div class="ds19-section-head"><h2>Стратегии A–F · цял период</h2></div><p class="helper">Историческият панел от Oracle временно не е достъпен.</p></section>';}
 const choices=[['all','Всички индивидуални селекции'],['best','Best of the Day · сингли'],['bestBuilders','Best of the Day · билдъри'],['builders','Моите билдъри'],['A','A · Удари'],['B','B · Точни удари'],['C','C · Голове'],['D1','D1 · Победа'],['D2','D2 · Двоен шанс'],['D3','D3 · Полувреме'],['E','E · Гост 9/10'],['F','F · Гост над 2.00']];const selected=state.statSources;const oracle=state.statDataSource==='oracle';const query=(state.mode==='all'?'':('&from='+encodeURIComponent(iso(state.from))+'&to='+encodeURIComponent(iso(state.mode==='day'?state.from:state.to))))+'&sources='+encodeURIComponent((selected.length?selected.join(','):'none'));const d=oracle?await (async()=>{const response=await fetch('/api/oracle-stats?'+query.replace(/^&/,''),{headers:{Authorization:'Bearer '+state.token},cache:'no-store'});const data=await response.json().catch(()=>({error:'Невалиден отговор'}));if(!response.ok)throw Error(data.error||'Oracle stats '+response.status);return data})():await api('statistics',period()+'&sources='+encodeURIComponent((selected.length?selected.join(','):'none')));const x=d.selected;$('#content').innerHTML=`${historicalPanel}${dates()}<div class="segmented tabs"><button data-stat-source-system="oracle" class="${oracle?'active':''}">Oracle · Архив</button><button data-stat-source-system="sheets" class="${!oracle?'active':''}">Google Sheets · Текущи</button></div><p class="helper">${oracle?'Исторически уредени и чакащи селекции от Oracle. Best of the Day се оценява и като отделни сингли (1u на селекция), и като дневен билдър (1u на колонка). Това е моделна доходност, не доказателство за реално поставени залози.':'Текущи данни от Google Sheets. Не се сумират автоматично с архива.'}</p><div class="page-intro"><span class="tag">АНАЛИЗАТОР</span><h2>Създай своя анализ</h2><p>Комбинирай стратегии, селекции и билдъри. Повтарящите се селекции се броят само веднъж.</p></div><div class="saved-panel"><select id="saved-view" aria-label="Запазени анализи"><option value="">Запазени анализи…</option>${Object.keys(state.savedViews).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select><button id="save-view" class="btn blue">+ Запази</button><button id="delete-view" class="btn outline" title="Изтрий избрания анализ">Изтрий</button></div><div class="selection-panel"><div class="selection-head"><b>Източници на резултати</b><button id="stat-all" class="text-link">Избери всички</button><button id="stat-clear" class="text-link">Изчисти</button></div><div class="check-grid">${choices.map(([key,label])=>`<label class="check-chip ${selected.includes(key)?'chosen':''}"><input type="checkbox" data-stat-source="${key}" ${selected.includes(key)?'checked':''}><span class="check-symbol">${selected.includes(key)?'✓':'+'}</span>${esc(label)}</label>`).join('')}</div></div>${section('Резултат за избраната комбинация')}<div class="selected-caption">${selected.length?`${selected.length} избрани категории`:'Няма избрани категории'}</div>${statCards(x)}${section('Развитие във времето')}<div class="v10-chart-note">Натрупана печалба в единици за избрания период</div>${chart(d.daily)}<div class="detail-stats"><div><span>Уредени</span><b>${fmt(x.settled)}</b></div><div><span>Печеливши</span><b class="positive">${fmt(x.wins)}</b></div><div><span>Губещи</span><b class="negative">${fmt(x.losses)}</b></div><div><span>Чакащи</span><b>${fmt(x.pending)}</b></div></div>${oracle?`<div class="page-intro"><h2>Best of the Day · два начина на отчет</h2><p>Сингли: по 1u на всяка селекция. Билдър: по 1u на дневната колонка. Двете статистики са независими; при общ избор се сумират като различни залози.</p></div><div class="detail-stats"><div><span>Best сингли · ${fmt(d.best.count)}</span><b class="${color(d.best.profit)}">${signed(d.best.profit)}u · ${signed(d.best.yield)}% Yield · ${fmt(d.best.wr)}% WR</b></div><div><span>Best билдъри · ${fmt(d.bestBuilders.count)}</span><b class="${color(d.bestBuilders.profit)}">${signed(d.bestBuilders.profit)}u · ${signed(d.bestBuilders.yield)}% Yield · ${fmt(d.bestBuilders.wr)}% WR</b></div></div>`:''}${section('Стратегии A–F · '+(oracle?'цялата история в Oracle':'избран период в Google Sheets'))}<div class="v10-comparison">${d.groups.map(g=>`<div class="v10-comparison-row"><span>${esc(g.key)}</span><div class="v10-bar"><i style="width:${Math.max(2,Math.min(100,50+Number(g.stats.yield||0)))}%"></i></div><b class="${color(g.stats.yield)}">${signed(g.stats.yield)}%</b></div>`).join('')}</div><div class="strategy-stack">${d.groups.map(g=>`<button class="strategy-line" data-stat-key="${g.key}">${strategyBadge(g.key)}<span class="line-info"><b>${esc(g.name)}</b><small>${fmt(g.stats.count)} селекции · ${fmt(g.stats.wr)}% WR</small></span><span class="line-result ${color(g.stats.profit)}">${signed(g.stats.profit)}u<small>${signed(g.stats.yield)}% Yield</small></span></button>`).join('')}</div>`;bindDates();bindLinks();document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.statSources=[b.dataset.open];state.statDataSource='oracle';state.mode='all';render()});document.querySelectorAll('[data-stat-source-system]').forEach(b=>b.onclick=()=>{state.statDataSource=b.dataset.statSourceSystem;state.mode='all';render()});$('#save-view').onclick=()=>{const name=prompt('Име на анализа:');if(!name||!name.trim())return;state.savedViews[name.trim()]=[...state.statSources];localStorage.setItem('ds-views',JSON.stringify(state.savedViews));render()};$('#saved-view').onchange=e=>{if(state.savedViews[e.target.value]){state.statSources=[...state.savedViews[e.target.value]];render()}};$('#delete-view').onclick=()=>{const name=$('#saved-view').value;if(!name)return;delete state.savedViews[name];localStorage.setItem('ds-views',JSON.stringify(state.savedViews));render()};document.querySelectorAll('[data-stat-source]').forEach(input=>input.onchange=()=>{const k=input.dataset.statSource;state.statSources=input.checked?[...new Set([...state.statSources,k])]:state.statSources.filter(v=>v!==k);render()});$('#stat-all').onclick=()=>{state.statSources=choices.map(v=>v[0]);render()};$('#stat-clear').onclick=()=>{state.statSources=[];render()};document.querySelectorAll('[data-stat-key]').forEach(b=>b.onclick=()=>{state.statSources=[b.dataset.statKey];render()})}
