const archiveState={kind:'matches',offset:0,limit:50};
function dsArchiveMatchHTML(match,league){const teams=teamNames(match);return teams.length===2?'<span class="ds22-archive-match"><span class="ds22-inline-crests">'+teams.map(t=>crestHTML(t,league)).join('')+'</span>'+esc(match||'')+'</span>':esc(match||'—')}
async function archive(){
 const kind=archiveState.kind;
 const dateFilter=state.mode==='all'?'':('&from='+encodeURIComponent(iso(state.from))+'&to='+encodeURIComponent(iso(state.mode==='day'?state.from:state.to)));const url='/api/history?kind='+encodeURIComponent(kind)+'&limit='+archiveState.limit+'&offset='+archiveState.offset+dateFilter;
 const response=await fetch(url,{headers:{Authorization:'Bearer '+state.token},cache:'no-store'});
 const data=await response.json().catch(()=>({error:'Невалиден отговор'}));
 if(response.status===401){state.token='';sessionStorage.removeItem('ds-token');$('#login').showModal()}
 if(!response.ok)throw Error(data.error||'Грешка '+response.status);
 const titles={matches:'Всички мачове',selections:'Всички селекции',best:'✧ Best of the Day',strategies:'Стратегии A–F',builders:'Билдъри',builderlegs:'Състав на билдърите',odds:'История на коефициентите'};
 const cols={matches:[['MATCH_DATE','Дата'],['MATCH_LABEL','Мач'],['LEAGUE','Лига'],['FINAL_SCORE','Резултат']],selections:[['MATCH_DATE','Дата'],['MATCH_LABEL','Мач'],['SELECTION_LABEL','Селекция'],['ODDS','Коеф.'],['IS_BEST','Best ✧'],['RESULT_STATUS','Статус'],['PROFIT_UNITS','Печалба (u)']],best:[['MATCH_DATE','Дата'],['MATCH_LABEL','Мач'],['SELECTION_LABEL','Селекция'],['ODDS','Коеф.'],['RESULT_STATUS','Статус'],['PROFIT_UNITS','Печалба (u)']],strategies:[['MATCH_DATE','Дата'],['STRATEGY_ID','Категория'],['MATCH_LABEL','Мач'],['SELECTION_LABEL','Селекция'],['ODDS','Коеф.'],['RESULT_STATUS','Статус'],['PROFIT_UNITS','P/L (u)']],builders:[['MATCH_DATE','Дата'],['BUILDER_TYPE','Тип'],['LEGS','Селекции'],['ODDS','Общ коеф.'],['RESULT_STATUS','Статус'],['PROFIT_UNITS','P/L (u)']],builderlegs:[['MATCH_DATE','Дата'],['BUILDER_TYPE','Тип'],['LEG_NUMBER','№'],['MATCH_LABEL','Мач'],['SELECTION_LABEL','Селекция'],['ODDS','Коеф.'],['RESULT_STATUS','Резултат']],odds:[['OBSERVED_DATE','Дата на наблюдение'],['MATCH_DATE','Дата на мача'],['MATCH_LABEL','Мач'],['SELECTION_LABEL','Селекция'],['DECIMAL_ODDS','Коеф.']]};
 const rows=Array.isArray(data.items)?data.items:[];
 $('#content').innerHTML=dates()+'<div class="page-intro"><span class="tag">ORACLE DATABASE</span><h2>Исторически архив</h2><p>Всички селекции са на едно място. Best of the Day е отделен подбор без повторно отчитане. Данните в Google Sheets остават непроменени.</p></div><div class="filter-panel"><div class="segmented">'+Object.entries(titles).map(([k,v])=>'<button data-archive-kind="'+k+'" class="'+(kind===k?'active':'')+'">'+v+'</button>').join('')+'</div></div>'+(!rows.length?empty('Няма записи в тази категория.'):'<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr>'+cols[kind].map(c=>'<th style="padding:12px 9px;border-bottom:1px solid #46536a">'+esc(c[1])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols[kind].map(c=>'<td style="padding:10px 9px;border-bottom:1px solid #293243;min-width:85px">'+c[0]==='MATCH_LABEL'?dsArchiveMatchHTML(r.MATCH_LABEL,r.LEAGUE):esc(c[0]==='IS_BEST'?(Number(r.IS_BEST)===1?'✧':'—'):(r[c[0]]??'—'))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>')+'<div class="filter-panel" style="display:flex;align-items:center;justify-content:space-between;gap:12px"><button class="btn outline" id="archive-prev" '+(archiveState.offset===0?'disabled':'')+'>← Назад</button><span>'+esc(String(archiveState.offset+1))+'–'+esc(String(archiveState.offset+rows.length))+'</span><button class="btn blue" id="archive-next" '+(!data.hasMore?'disabled':'')+'>Напред →</button></div>';
 bindDates();
 document.querySelectorAll('[data-archive-kind]').forEach(b=>b.onclick=()=>{archiveState.kind=b.dataset.archiveKind;archiveState.offset=0;render()});
 $('#archive-prev').onclick=()=>{archiveState.offset=Math.max(0,archiveState.offset-archiveState.limit);render()};
 $('#archive-next').onclick=()=>{archiveState.offset+=archiveState.limit;render()};
 hydrateCrests();
}
let requestId=0;async function render(){const n=++requestId;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));$('#title').textContent=headings[state.tab][0];$('#subtitle').textContent=headings[state.tab][1];$('#eyebrow').textContent=state.tab==='home'?'КОНТРОЛЕН ЦЕНТЪР':'DEEPSTATS';$('#content').innerHTML='<div class="loading"><span class="spinner"></span>Зареждане на данните…</div>';try{if(state.tab==='home')await home();if(state.tab==='matches')await matches();if(state.tab==='strategies')await strategies();if(state.tab==='builders')await builders();if(state.tab==='statistics')await statistics();if(state.tab==='archive')await archive();if(state.tab==='profile')profile()}catch(e){if(n===requestId)showError(e.message)}}
$('#refresh').onclick=()=>render();document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>setTheme(currentTheme==='dark'?'light':'dark'));updateThemeControls();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>nav(b.dataset.tab));$('#login-form').onsubmit=e=>{e.preventDefault();state.token=$('#token').value;sessionStorage.setItem('ds-token',state.token);$('#login').close();render()};if(!state.token)$('#login').showModal();else render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
